extends CharacterBody2D

signal died(enemy: Node)

@export var max_health: float = 50.0
@export var movement_speed: float = 100.0
@export var attack_damage: float = 10.0
@export var attack_interval: float = 1.0
@export var enemy_size: Vector2 = Vector2(24.0, 24.0)
@export var body_color: Color = Color(0.65, 0.05, 0.05, 1.0)
@export var target_refresh_interval: float = 0.75
@export var attack_range_padding: float = 6.0

@onready var sprite: Sprite2D = $Sprite2D
@onready var collision_shape: CollisionShape2D = $CollisionShape2D
@onready var health_bar: ProgressBar = $HealthBar
@onready var attack_timer: Timer = $AttackTimer
@onready var retarget_timer: Timer = $RetargetTimer

var current_health: float
var level: Node
var current_target: Node = null
var current_target_cell: Vector2i = Vector2i.ZERO
var current_target_world: Vector2 = Vector2.ZERO
var _dead := false
var _debug_click_damage := 25.0

func _ready() -> void:
	current_health = max_health
	z_index = 3
	add_to_group("enemies")
	_configure_visuals()
	_update_health_bar()
	attack_timer.wait_time = max(attack_interval, 0.05)
	attack_timer.one_shot = false
	retarget_timer.wait_time = max(target_refresh_interval, 0.1)
	retarget_timer.one_shot = false
	attack_timer.timeout.connect(_on_attack_timer_timeout)
	retarget_timer.timeout.connect(_on_retarget_timer_timeout)
	retarget_timer.start()
	level = get_parent()
	while level != null and not level.has_method("find_nearest_structure_target"):
		level = level.get_parent()
	acquire_target()

func _physics_process(_delta: float) -> void:
	if _dead:
		velocity = Vector2.ZERO
		move_and_slide()
		return

	if Input.is_action_just_pressed("ui_accept"):
		if global_position.distance_to(get_global_mouse_position()) <= max(enemy_size.x, enemy_size.y) * 1.5:
			take_damage(_debug_click_damage)

	if not _is_target_valid():
		acquire_target()

	if not _is_target_valid():
		velocity = Vector2.ZERO
		move_and_slide()
		return

	current_target_world = _get_attack_position_for_target(current_target, current_target_cell)
	var to_target := current_target_world - global_position
	var attack_distance := _get_attack_distance_for_target(current_target)
	if to_target.length() <= attack_distance:
		velocity = Vector2.ZERO
		move_and_slide()
		_start_attacking()
		return

	_stop_attacking()
	var desired_direction := to_target.normalized()
	velocity = desired_direction * movement_speed
	move_and_slide()

	if get_slide_collision_count() > 0:
		for i in range(get_slide_collision_count()):
			var collision := get_slide_collision(i)
			if collision == null:
				continue
			var collider := collision.get_collider()
			if collider == null:
				continue
			var structure := _resolve_structure_from_collider(collider)
			if structure != null and structure != current_target:
				current_target = structure
				if current_target.has_method("get_anchor_cell"):
					current_target_cell = current_target.get_anchor_cell()
				current_target_world = _get_attack_position_for_target(current_target, current_target_cell)
				velocity = Vector2.ZERO
				_start_attacking()
				break

func acquire_target() -> void:
	_stop_attacking()
	current_target = null
	if level == null or not level.has_method("find_nearest_structure_target"):
		return
	var target_data = level.find_nearest_structure_target(global_position)
	if typeof(target_data) != TYPE_DICTIONARY or target_data.is_empty():
		return
	var node: Node = target_data.get("node", null)
	if node == null or not is_instance_valid(node):
		return
	current_target = node
	current_target_cell = target_data.get("cell", Vector2i.ZERO)
	current_target_world = target_data.get("world_position", node.global_position)

func take_damage(amount: float) -> void:
	if _dead or amount <= 0.0:
		return
	current_health = clamp(current_health - amount, 0.0, max_health)
	_update_health_bar()
	if current_health <= 0.0:
		die()

func die() -> void:
	if _dead:
		return
	_dead = true
	velocity = Vector2.ZERO
	_stop_attacking()
	current_target = null
	emit_signal("died", self)
	queue_free()

func _on_attack_timer_timeout() -> void:
	if _dead or not _is_target_valid():
		_stop_attacking()
		return
	var distance := global_position.distance_to(_get_attack_position_for_target(current_target, current_target_cell))
	if distance > _get_attack_distance_for_target(current_target) + 4.0:
		_stop_attacking()
		return
	if current_target.has_method("take_damage"):
		current_target.take_damage(attack_damage)
	if not _is_target_valid():
		acquire_target()

func _on_retarget_timer_timeout() -> void:
	if _dead:
		return
	if level == null or not level.has_method("find_nearest_structure_target"):
		return
	var target_data = level.find_nearest_structure_target(global_position)
	if typeof(target_data) != TYPE_DICTIONARY or target_data.is_empty():
		if not _is_target_valid():
			current_target = null
		return
	var node: Node = target_data.get("node", null)
	if node == null or not is_instance_valid(node):
		return
	if current_target == null or node != current_target:
		current_target = node
		current_target_cell = target_data.get("cell", Vector2i.ZERO)
		current_target_world = target_data.get("world_position", node.global_position)
	elif target_data.has("cell"):
		current_target_cell = target_data.get("cell", current_target_cell)
		current_target_world = target_data.get("world_position", current_target_world)

func _is_target_valid() -> bool:
	if current_target == null or not is_instance_valid(current_target):
		return false
	if current_target.has_method("is_destroyed") and current_target.is_destroyed():
		return false
	if current_target.has_method("is_structure_alive"):
		return current_target.is_structure_alive()
	return true

func _start_attacking() -> void:
	if attack_timer.is_stopped():
		attack_timer.start()

func _stop_attacking() -> void:
	if not attack_timer.is_stopped():
		attack_timer.stop()

func _get_attack_position_for_target(target: Node, target_cell: Vector2i) -> Vector2:
	if target == null:
		return global_position
	if target.has_method("get_closest_attack_point"):
		return target.get_closest_attack_point(global_position)
	if target.has_method("get_cell_world_center"):
		return target.get_cell_world_center(target_cell)
	return target.global_position

func _get_attack_distance_for_target(target: Node) -> float:
	var own_radius := max(enemy_size.x, enemy_size.y) * 0.5
	if target != null and target.has_method("get_attack_radius"):
		return own_radius + float(target.get_attack_radius()) + attack_range_padding
	return own_radius + attack_range_padding

func _resolve_structure_from_collider(collider: Object) -> Node:
	if collider == null:
		return null
	var node := collider as Node
	while node != null:
		if node.is_in_group("structure_targets"):
			return node
		node = node.get_parent()
	return null

func _configure_visuals() -> void:
	var image := Image.create(max(int(enemy_size.x), 1), max(int(enemy_size.y), 1), false, Image.FORMAT_RGBA8)
	image.fill(body_color)
	var texture := ImageTexture.create_from_image(image)
	sprite.texture = texture
	sprite.centered = true
	var rect := RectangleShape2D.new()
	rect.size = enemy_size
	collision_shape.shape = rect
	health_bar.custom_minimum_size = Vector2(max(enemy_size.x + 8.0, 24.0), 8.0)
	health_bar.size = health_bar.custom_minimum_size
	health_bar.position = Vector2(-health_bar.custom_minimum_size.x * 0.5, -enemy_size.y * 0.5 - 14.0)

func _update_health_bar() -> void:
	health_bar.min_value = 0.0
	health_bar.max_value = max_health
	health_bar.value = current_health
	health_bar.show_percentage = false
	health_bar.visible = current_health < max_health
	var ratio := current_health / max_health if max_health > 0.0 else 0.0
	if ratio > 0.6:
		health_bar.modulate = Color(0.2, 0.9, 0.2, 1.0)
	elif ratio > 0.3:
		health_bar.modulate = Color(1.0, 0.85, 0.2, 1.0)
	else:
		health_bar.modulate = Color(1.0, 0.2, 0.2, 1.0)

extends Node2D

@export var enemy_scene: PackedScene = preload("res://Enemies/enemy.tscn")
@export_node_path("Camera2D") var camera_path: NodePath = ^"../Camera2D"
@export_node_path("TileMapLayer") var ground_path: NodePath = ^"../Ground"
@export_node_path("Node2D") var enemies_container_path: NodePath = ^"../Enemies"
@export var spawn_interval: float = 3.0
@export var max_enemies: int = 30
@export var spawn_offset: float = 32.0
@export var max_spawn_attempts: int = 20

@onready var camera: Camera2D = get_node_or_null(camera_path) as Camera2D
@onready var ground: TileMapLayer = get_node_or_null(ground_path) as TileMapLayer
@onready var enemies_container: Node2D = get_node_or_null(enemies_container_path) as Node2D
@onready var spawn_timer: Timer = $SpawnTimer

var active_enemies: Array[Node] = []
var level: Node

func _ready() -> void:
	randomize()
	level = get_parent()
	spawn_timer.wait_time = max(spawn_interval, 0.1)
	spawn_timer.one_shot = false
	spawn_timer.timeout.connect(_on_spawn_timer_timeout)
	spawn_timer.start()

func _on_spawn_timer_timeout() -> void:
	_cleanup_enemy_list()
	if enemy_scene == null or camera == null or ground == null or enemies_container == null:
		return
	if active_enemies.size() >= max_enemies:
		return
	var spawn_position := _find_spawn_position()
	if spawn_position == null:
		return
	var enemy := enemy_scene.instantiate()
	if enemy == null:
		return
	enemies_container.add_child(enemy)
	enemy.global_position = spawn_position
	if enemy.has_signal("died"):
		enemy.died.connect(_on_enemy_died)
	active_enemies.append(enemy)

func _on_enemy_died(enemy: Node) -> void:
	active_enemies.erase(enemy)

func _cleanup_enemy_list() -> void:
	active_enemies = active_enemies.filter(func(enemy: Node) -> bool: return enemy != null and is_instance_valid(enemy) and not enemy.is_queued_for_deletion())

func _find_spawn_position() -> Variant:
	var rect := _get_camera_world_rect()
	var used_rect := ground.get_used_rect()
	for _i in range(max_spawn_attempts):
		var side := randi() % 4
		var world_position := Vector2.ZERO
		match side:
			0:
				world_position = Vector2(randf_range(rect.position.x, rect.end.x), rect.position.y - spawn_offset)
			1:
				world_position = Vector2(randf_range(rect.position.x, rect.end.x), rect.end.y + spawn_offset)
			2:
				world_position = Vector2(rect.position.x - spawn_offset, randf_range(rect.position.y, rect.end.y))
			3:
				world_position = Vector2(rect.end.x + spawn_offset, randf_range(rect.position.y, rect.end.y))
		var local := ground.to_local(world_position)
		var cell := ground.local_to_map(local)
		cell.x = clampi(cell.x, used_rect.position.x, used_rect.position.x + used_rect.size.x - 1)
		cell.y = clampi(cell.y, used_rect.position.y, used_rect.position.y + used_rect.size.y - 1)
		if level != null and level.has_method("is_cell_occupied") and level.is_cell_occupied(cell):
			continue
		var adjusted_world := ground.to_global(ground.map_to_local(cell))
		if level != null and level.has_method("is_world_position_near_structure") and level.is_world_position_near_structure(adjusted_world, 12.0):
			continue
		return adjusted_world
	return null

func _get_camera_world_rect() -> Rect2:
	var viewport := get_viewport()
	var visible_size := viewport.get_visible_rect().size
	var zoom := camera.zoom
	var size := Vector2(visible_size.x * zoom.x, visible_size.y * zoom.y)
	var center := camera.get_screen_center_position()
	return Rect2(center - size * 0.5, size)

extends Node2D

signal structure_added(structure: Node)
signal structure_removed(structure: Node)

@export_node_path("TileMapLayer") var ground_path: NodePath = ^"../Ground"
@export_node_path("Button") var build_button_path: NodePath = ^"../BuildModeUI/BuildModeButton"
@export var block_max_health: float = 100.0

const BLOCK_COLOR := Color(1.0, 0.0, 0.0, 1.0)
const PREVIEW_COLOR := Color(1.0, 0.0, 0.0, 0.45)
const GRID_COLOR := Color(1.0, 1.0, 1.0, 0.35)
const GRID_LINE_WIDTH := 2.0

var build_mode_enabled := false
var occupied_cells: Dictionary = {}
var hovered_cell: Vector2i
var has_hovered_cell := false
var used_rect: Rect2i
var reserved_cells: Dictionary = {}
var block_structures: Dictionary = {}

@onready var ground: TileMapLayer = get_node(ground_path) as TileMapLayer
@onready var build_button: Button = get_node_or_null(build_button_path) as Button

func _ready() -> void:
	if ground == null:
		push_error("BuildSystem: Ground TileMapLayer not found.")
		set_process(false)
		set_process_unhandled_input(false)
		return

	used_rect = ground.get_used_rect()
	z_index = max(ground.z_index + 1, 1)
	_refresh_reserved_cells()
	set_process(true)
	set_process_unhandled_input(true)
	_update_button_visuals()
	queue_redraw()

func _process(_delta: float) -> void:
	_refresh_reserved_cells()
	if not build_mode_enabled:
		if has_hovered_cell:
			has_hovered_cell = false
			queue_redraw()
		return

	var next_hovered := _get_cell_under_mouse()
	var next_has_hovered := _is_cell_buildable(next_hovered)
	if next_has_hovered != has_hovered_cell or (next_has_hovered and next_hovered != hovered_cell):
		has_hovered_cell = next_has_hovered
		hovered_cell = next_hovered
		queue_redraw()

func _unhandled_input(event: InputEvent) -> void:
	if not build_mode_enabled:
		return

	if event is InputEventMouseButton \
	and event.button_index == MOUSE_BUTTON_LEFT \
	and event.pressed \
	and not event.is_echo():
		if _is_mouse_over_control():
			return
		var cell := _get_cell_under_mouse()
		if not _is_cell_buildable(cell):
			return
		if occupied_cells.has(cell):
			return
		_create_block(cell)
		queue_redraw()
		get_viewport().set_input_as_handled()

func set_build_mode_enabled(enabled: bool) -> void:
	if build_mode_enabled == enabled:
		return
	build_mode_enabled = enabled
	if not build_mode_enabled:
		has_hovered_cell = false
	_update_button_visuals()
	queue_redraw()

func toggle_build_mode() -> void:
	set_build_mode_enabled(not build_mode_enabled)

func get_structure_nodes() -> Array[Node]:
	var result: Array[Node] = []
	for node in block_structures.values():
		if node != null and is_instance_valid(node):
			result.append(node)
	return result

func has_occupied_cell(cell: Vector2i) -> bool:
	return occupied_cells.has(cell)

func get_cell_world_center(cell: Vector2i) -> Vector2:
	return ground.to_global(ground.map_to_local(cell))

func get_cell_size_world() -> Vector2:
	return Vector2(ground.tile_set.tile_size) * ground.global_scale

func _create_block(cell: Vector2i) -> void:
	var block := StaticBody2D.new()
	block.name = "Block_%s_%s" % [cell.x, cell.y]
	block.set_meta("cell", cell)
	block.set_meta("max_health", block_max_health)
	block.set_meta("current_health", block_max_health)
	block.add_to_group("structure_targets")
	block.add_to_group("player_blocks")
	block.collision_layer = 2
	block.collision_mask = 1
	add_child(block)

	var visual := Polygon2D.new()
	var size := get_cell_size_world()
	var half := size * 0.5
	visual.polygon = PackedVector2Array([
		Vector2(-half.x, -half.y),
		Vector2(half.x, -half.y),
		Vector2(half.x, half.y),
		Vector2(-half.x, half.y)
	])
	visual.color = BLOCK_COLOR
	block.add_child(visual)

	var collision := CollisionShape2D.new()
	var rect := RectangleShape2D.new()
	rect.size = size
	collision.shape = rect
	block.add_child(collision)

	var health_bar := ProgressBar.new()
	health_bar.name = "HealthBar"
	health_bar.custom_minimum_size = Vector2(max(size.x, 24.0), 8.0)
	health_bar.size = health_bar.custom_minimum_size
	health_bar.position = Vector2(-health_bar.custom_minimum_size.x * 0.5, -half.y - 14.0)
	health_bar.show_percentage = false
	block.add_child(health_bar)

	block.position = to_local(get_cell_world_center(cell))
	block.set_script(_create_block_script())
	block.call("setup_block", self, cell)
	occupied_cells[cell] = true
	block_structures[cell] = block
	emit_signal("structure_added", block)

func destroy_block_at_cell(cell: Vector2i) -> void:
	var block: Node = block_structures.get(cell, null)
	if block == null or not is_instance_valid(block):
		occupied_cells.erase(cell)
		block_structures.erase(cell)
		queue_redraw()
		return
	emit_signal("structure_removed", block)
	occupied_cells.erase(cell)
	block_structures.erase(cell)
	block.queue_free()
	queue_redraw()

func _create_block_script() -> Script:
	var script := GDScript.new()
	script.source_code = "extends StaticBody2D\nvar build_system: Node\nvar cell: Vector2i\nvar destroyed := false\nfunc setup_block(owner_build_system: Node, owner_cell: Vector2i) -> void:\n\tbuild_system = owner_build_system\n\tcell = owner_cell\n\t_update_health_bar()\nfunc take_damage(amount: float) -> void:\n\tif destroyed or amount <= 0.0:\n\t\treturn\n\tvar current_health: float = float(get_meta(\"current_health\", 0.0)) - amount\n\tset_meta(\"current_health\", max(current_health, 0.0))\n\t_update_health_bar()\n\tif current_health <= 0.0:\n\t\tdestroyed = true\n\t\tif build_system != null and is_instance_valid(build_system):\n\t\t\tbuild_system.destroy_block_at_cell(cell)\nfunc is_structure_alive() -> bool:\n\treturn not destroyed and float(get_meta(\"current_health\", 0.0)) > 0.0\nfunc is_destroyed() -> bool:\n\treturn destroyed or float(get_meta(\"current_health\", 0.0)) <= 0.0\nfunc get_anchor_cell() -> Vector2i:\n\treturn cell\nfunc get_occupied_cells() -> Array[Vector2i]:\n\treturn [cell]\nfunc get_cell_world_center(query_cell: Vector2i = cell) -> Vector2:\n\tif build_system != null and is_instance_valid(build_system):\n\t\treturn build_system.get_cell_world_center(query_cell)\n\treturn global_position\nfunc get_closest_attack_point(from_world: Vector2) -> Vector2:\n\treturn global_position\nfunc get_attack_radius() -> float:\n\tif build_system != null and is_instance_valid(build_system):\n\t\tvar size := build_system.get_cell_size_world()\n\t\treturn max(size.x, size.y) * 0.5\n\treturn 16.0\nfunc _update_health_bar() -> void:\n\tvar bar := get_node_or_null(\"HealthBar\") as ProgressBar\n\tif bar == null:\n\t\treturn\n\tvar max_health := float(get_meta(\"max_health\", 1.0))\n\tvar current_health := float(get_meta(\"current_health\", max_health))\n\tbar.min_value = 0.0\n\tbar.max_value = max_health\n\tbar.value = current_health\n\tbar.visible = current_health < max_health\n\tvar ratio := current_health / max_health if max_health > 0.0 else 0.0\n\tif ratio > 0.6:\n\t\tbar.modulate = Color(0.2, 0.9, 0.2, 1.0)\n\telif ratio > 0.3:\n\t\tbar.modulate = Color(1.0, 0.85, 0.2, 1.0)\n\telse:\n\t\tbar.modulate = Color(1.0, 0.2, 0.2, 1.0)\n"
	script.reload()
	return script

func _update_button_visuals() -> void:
	if build_button == null:
		return
	build_button.text = "Exit Build Mode" if build_mode_enabled else "Build Mode"
	build_button.button_pressed = build_mode_enabled
	build_button.modulate = Color(1.0, 0.75, 0.75, 1.0) if build_mode_enabled else Color(1.0, 1.0, 1.0, 1.0)

func _draw() -> void:
	if build_mode_enabled:
		_draw_grid()
		if has_hovered_cell and not occupied_cells.has(hovered_cell):
			_draw_filled_cell(hovered_cell, PREVIEW_COLOR)

func _draw_grid() -> void:
	if used_rect.size.x <= 0 or used_rect.size.y <= 0:
		return

	var bottom_right_cell := used_rect.position + used_rect.size
	var bottom_right := _cell_top_left(bottom_right_cell)

	for x in range(used_rect.position.x, used_rect.position.x + used_rect.size.x + 1):
		var start := _cell_top_left(Vector2i(x, used_rect.position.y))
		var finish := Vector2(start.x, bottom_right.y)
		draw_line(start, finish, GRID_COLOR, GRID_LINE_WIDTH)

	for y in range(used_rect.position.y, used_rect.position.y + used_rect.size.y + 1):
		var start := _cell_top_left(Vector2i(used_rect.position.x, y))
		var finish := Vector2(bottom_right.x, start.y)
		draw_line(start, finish, GRID_COLOR, GRID_LINE_WIDTH)

func _draw_filled_cell(cell: Vector2i, color: Color) -> void:
	var rect := Rect2(_cell_top_left(cell), _cell_size())
	draw_rect(rect, color, true)

func _get_cell_under_mouse() -> Vector2i:
	var mouse_world := get_global_mouse_position()
	var mouse_in_ground := ground.to_local(mouse_world)
	return ground.local_to_map(mouse_in_ground)

func _is_cell_buildable(cell: Vector2i) -> bool:
	return used_rect.has_point(cell) and not reserved_cells.has(cell)

func _refresh_reserved_cells() -> void:
	reserved_cells.clear()
	var level := get_parent()
	if level != null and level.has_method("get_server_occupied_cells"):
		for cell in level.get_server_occupied_cells():
			reserved_cells[cell] = true

func _cell_top_left(cell: Vector2i) -> Vector2:
	var local_center := ground.map_to_local(cell)
	var local_top_left := local_center - ground.tile_set.tile_size * 0.5
	return to_local(ground.to_global(local_top_left))

func _cell_size() -> Vector2:
	return Vector2(ground.tile_set.tile_size) * ground.global_scale

func _is_mouse_over_control() -> bool:
	var viewport := get_viewport()
	if viewport == null:
		return false
	var hovered := viewport.gui_get_hovered_control()
	return hovered != null

extends Node2D

signal server_destroyed

@export var width: float = 76.8
@export var height: float = 82.944
@export var max_health: float = 100.0
@export var current_health: float = 100.0
@export var occupied_size_in_cells: Vector2i = Vector2i(3, 3)
@export var visual_scale_multiplier: float = 1.35
@export var server_texture: Texture2D = preload("res://assets/server.png")

@onready var sprite: Sprite2D = $Sprite2D
@onready var health_bar: ProgressBar = $HealthBar
@onready var collision_shape: CollisionShape2D = $StaticBody2D/CollisionShape2D

var _destroyed_emitted := false
var anchor_cell: Vector2i = Vector2i.ZERO
var ground_ref: TileMapLayer

func _ready() -> void:
	z_index = 2
	add_to_group("structure_targets")
	max_health = max(max_health, 1.0)
	current_health = clamp(current_health, 0.0, max_health)
	_update_sprite_visual()
	_update_collision_shape()
	_update_health_bar()

func set_anchor_cell(value: Vector2i) -> void:
	anchor_cell = value

func set_ground_ref(value: TileMapLayer) -> void:
	ground_ref = value

func set_footprint_size(new_size: Vector2) -> void:
	width = max(new_size.x, 1.0)
	height = max(new_size.y, 1.0)
	_update_sprite_visual()
	_update_collision_shape()
	_update_health_bar()

func take_damage(amount: float) -> void:
	if amount <= 0.0 or current_health <= 0.0:
		return
	_set_current_health(current_health - amount)

func heal(amount: float) -> void:
	if amount <= 0.0:
		return
	_set_current_health(current_health + amount)

func is_structure_alive() -> bool:
	return current_health > 0.0

func is_destroyed() -> bool:
	return current_health <= 0.0

func get_anchor_cell() -> Vector2i:
	return anchor_cell

func get_attack_radius() -> float:
	return max(width, height) * 0.5

func get_closest_attack_point(from_world: Vector2) -> Vector2:
	var half := Vector2(width, height) * 0.5
	return Vector2(
		clampf(from_world.x, global_position.x - half.x, global_position.x + half.x),
		clampf(from_world.y, global_position.y - half.y, global_position.y + half.y)
	)

func get_cell_world_center(cell: Vector2i) -> Vector2:
	if ground_ref == null:
		return global_position
	return ground_ref.to_global(ground_ref.map_to_local(cell))

func get_occupied_cells(origin_cell: Vector2i = anchor_cell) -> Array[Vector2i]:
	var cells: Array[Vector2i] = []
	var start := origin_cell - Vector2i(occupied_size_in_cells.x >> 1, occupied_size_in_cells.y >> 1)
	for y in range(occupied_size_in_cells.y):
		for x in range(occupied_size_in_cells.x):
			cells.append(start + Vector2i(x, y))
	return cells

func _set_current_health(value: float) -> void:
	current_health = clamp(value, 0.0, max_health)
	_update_health_bar()
	if current_health <= 0.0 and not _destroyed_emitted:
		_destroyed_emitted = true
		emit_signal("server_destroyed")
	elif current_health > 0.0:
		_destroyed_emitted = false

func _update_sprite_visual() -> void:
	if not is_node_ready():
		return
	sprite.centered = true
	sprite.texture = server_texture
	if server_texture == null:
		sprite.scale = Vector2.ONE
		return
	var texture_size := server_texture.get_size()
	if texture_size.x <= 0.0 or texture_size.y <= 0.0:
		sprite.scale = Vector2.ONE
		return
	var scale_factor: float = min(width / texture_size.x, height / texture_size.y) * visual_scale_multiplier
	sprite.scale = Vector2.ONE * scale_factor

func _update_collision_shape() -> void:
	if not is_node_ready():
		return
	var rectangle := RectangleShape2D.new()
	rectangle.size = Vector2(width, height)
	collision_shape.shape = rectangle
	$StaticBody2D.collision_layer = 2
	$StaticBody2D.collision_mask = 1

func _update_health_bar() -> void:
	if not is_node_ready():
		return
	health_bar.min_value = 0.0
	health_bar.max_value = max_health
	health_bar.value = current_health
	health_bar.show_percentage = false
	health_bar.position = Vector2(-health_bar.size.x * 0.5, -height * 0.5 - 18.0)
	var ratio := current_health / max_health if max_health > 0.0 else 0.0
	if ratio > 0.6:
		health_bar.modulate = Color(0.2, 0.9, 0.2, 1.0)
	elif ratio > 0.3:
		health_bar.modulate = Color(1.0, 0.85, 0.2, 1.0)
	else:
		health_bar.modulate = Color(1.0, 0.2, 0.2, 1.0)

extends Node2D

@export_node_path("TileMapLayer") var ground_path: NodePath = ^"Ground"
@export_node_path("Camera2D") var camera_path: NodePath = ^"Camera2D"
@export_node_path("Node2D") var build_system_path: NodePath = ^"BuildSystem"
@export var server_scene: PackedScene = preload("res://server.tscn")

@onready var ground: TileMapLayer = get_node(ground_path) as TileMapLayer
@onready var camera: Camera2D = get_node_or_null(camera_path) as Camera2D
@onready var build_system: Node2D = get_node_or_null(build_system_path) as Node2D

var server_instance: Node2D
var server_anchor_cell: Vector2i

func _ready() -> void:
	if ground == null:
		push_error("Level: Ground TileMapLayer not found.")
		return
	_spawn_server()
	_center_camera_on_server()

func get_server() -> Node2D:
	return server_instance

func get_server_occupied_cells() -> Array[Vector2i]:
	if server_instance == null or not server_instance.has_method("get_occupied_cells"):
		return []
	return server_instance.get_occupied_cells(server_anchor_cell)

func get_all_structure_nodes() -> Array[Node]:
	var result: Array[Node] = []
	if server_instance != null and is_instance_valid(server_instance) and (not server_instance.has_method("is_structure_alive") or server_instance.is_structure_alive()):
		result.append(server_instance)
	if build_system != null and build_system.has_method("get_structure_nodes"):
		for node in build_system.get_structure_nodes():
			if node != null and is_instance_valid(node):
				result.append(node)
	return result

func is_cell_occupied(cell: Vector2i) -> bool:
	if build_system != null and build_system.has_method("has_occupied_cell") and build_system.has_occupied_cell(cell):
		return true
	return cell in get_server_occupied_cells()

func is_world_position_near_structure(world_position: Vector2, padding: float = 0.0) -> bool:
	for structure in get_all_structure_nodes():
		if structure == null or not is_instance_valid(structure):
			continue
		var radius := 16.0
		if structure.has_method("get_attack_radius"):
			radius = float(structure.get_attack_radius())
		if structure.global_position.distance_to(world_position) <= radius + padding:
			return true
	return false

func find_nearest_structure_target(from_world: Vector2) -> Dictionary:
	var best: Dictionary = {}
	var best_distance := INF
	for structure in get_all_structure_nodes():
		if structure == null or not is_instance_valid(structure):
			continue
		if structure.has_method("is_structure_alive") and not structure.is_structure_alive():
			continue
		var cells: Array = []
		if structure.has_method("get_occupied_cells"):
			cells = structure.get_occupied_cells(structure.get_anchor_cell() if structure.has_method("get_anchor_cell") else Vector2i.ZERO)
		else:
			cells = []
		if cells.is_empty():
			var distance_to_node := from_world.distance_squared_to(structure.global_position)
			if distance_to_node < best_distance:
				best_distance = distance_to_node
				best = {"node": structure, "cell": Vector2i.ZERO, "world_position": structure.global_position}
			continue
		for cell in cells:
			var world := _get_cell_center_world(cell)
			var distance := from_world.distance_squared_to(world)
			if distance < best_distance:
				best_distance = distance
				best = {"node": structure, "cell": cell, "world_position": world}
	return best

func _spawn_server() -> void:
	if server_scene == null:
		push_error("Level: server_scene is not assigned.")
		return
	if server_instance != null:
		server_instance.queue_free()
	server_instance = server_scene.instantiate() as Node2D
	if server_instance == null:
		push_error("Level: Failed to instantiate server scene.")
		return
	add_child(server_instance)
	server_anchor_cell = _get_map_center_anchor_cell()
	server_instance.global_position = _get_footprint_center_world(server_anchor_cell, Vector2i(3, 3))
	if server_instance.has_method("set_footprint_size"):
		server_instance.set_footprint_size(_get_cell_world_size() * Vector2(3, 3))
	if server_instance.has_method("set_anchor_cell"):
		server_instance.set_anchor_cell(server_anchor_cell)
	if server_instance.has_method("set_ground_ref"):
		server_instance.set_ground_ref(ground)

func _center_camera_on_server() -> void:
	if camera == null or server_instance == null:
		return
	camera.global_position = server_instance.global_position
	camera.make_current()
	camera.reset_smoothing()
	camera.force_update_scroll()

func _get_map_center_anchor_cell() -> Vector2i:
	var used_rect := ground.get_used_rect()
	var center_local := used_rect.position + Vector2i(used_rect.size.x >> 1, used_rect.size.y >> 1)
	return Vector2i(center_local)

func _get_footprint_center_world(anchor_cell: Vector2i, footprint: Vector2i) -> Vector2:
	var start := anchor_cell - Vector2i(footprint.x >> 1, footprint.y >> 1)
	var end := start + footprint - Vector2i.ONE
	var start_world := _get_cell_center_world(start)
	var end_world := _get_cell_center_world(end)
	return (start_world + end_world) * 0.5

func _get_cell_center_world(cell: Vector2i) -> Vector2:
	return ground.to_global(ground.map_to_local(cell))

func _get_cell_world_size() -> Vector2:
	return Vector2(ground.tile_set.tile_size) * ground.global_scale

